00049 enum AlfFilterType
00050 {
00051   ALF_FILTER_5,
00052   ALF_FILTER_7,
00053   CC_ALF,
00054   ALF_NUM_OF_FILTER_TYPES
00055 };
00056 
00057 
00058 static const int size_CC_ALF = -1;
00059 
00060 struct AlfFilterShape
00061 {
00062   AlfFilterShape( int size )
00063     : filterLength( size ),
00064     numCoeff( size * size / 4 + 1 ),
00065     filterSize( size * size / 2 + 1 )
00066   {
00067     if( size == 5 )
00068     {
00069       pattern = {
00070                  0,
00071              1,  2,  3,
00072          4,  5,  6,  5,  4,
00073              3,  2,  1,
00074                  0
00075       };
00076 
00077       weights = {
00078                  2,
00079               2, 2, 2,
00080            2, 2, 1, 1
00081       };
00082 
00083       filterType = ALF_FILTER_5;
00084     }
00085     else if( size == 7 )
00086     {
00087       pattern = {
00088                      0,
00089                  1,  2,  3,
00090              4,  5,  6,  7,  8,
00091          9, 10, 11, 12, 11, 10, 9,
00092              8,  7,  6,  5,  4,
00093                  3,  2,  1,
00094                      0
00095       };
00096 
00097       weights = {
00098                     2,
00099                 2,  2,  2,
00100             2,  2,  2,  2,  2,
00101         2,  2,  2,  1,  1
00102       };
00103 
00104       filterType = ALF_FILTER_7;
00105     }
00106     else if (size == size_CC_ALF)
00107     {
00108       size = 4;
00109       filterLength = 8;
00110       numCoeff = 8;
00111       filterSize = 8;
00112       filterType   = CC_ALF;
00113     }
00114     else
00115     {
00116       filterType = ALF_NUM_OF_FILTER_TYPES;
00117       CHECK( 0, "Wrong ALF filter shape" );
00118     }
00119   }
00120 
00121   AlfFilterType filterType;
00122   int filterLength;
00123   int numCoeff;      //TO DO: check whether we need both numCoeff and filterSize
00124   int filterSize;
00125   std::vector<int> pattern;
00126   std::vector<int> weights;
00127 };
00128 
00129 struct AlfParam
00130 {
00131   bool                         enabledFlag[MAX_NUM_COMPONENT];                          // alf_slice_enable_flag, alf_chroma_idc
00132   bool                         nonLinearFlag[MAX_NUM_CHANNEL_TYPE];                     // alf_[luma/chroma]_clip_flag
00133   short                        lumaCoeff[MAX_NUM_ALF_CLASSES * MAX_NUM_ALF_LUMA_COEFF]; // alf_coeff_luma_delta[i][j]
00134   Pel                          lumaClipp[MAX_NUM_ALF_CLASSES * MAX_NUM_ALF_LUMA_COEFF]; // alf_clipp_luma_[i][j]
00135   int                          numAlternativesChroma;                                                  // alf_chroma_num_alts_minus_one + 1
00136   short                        chromaCoeff[MAX_NUM_ALF_ALTERNATIVES_CHROMA][MAX_NUM_ALF_CHROMA_COEFF]; // alf_coeff_chroma[i]
00137   Pel                          chromaClipp[MAX_NUM_ALF_ALTERNATIVES_CHROMA][MAX_NUM_ALF_CHROMA_COEFF]; // alf_clipp_chroma[i]
00138   short                        filterCoeffDeltaIdx[MAX_NUM_ALF_CLASSES];                // filter_coeff_delta[i]
00139   bool                         alfLumaCoeffFlag[MAX_NUM_ALF_CLASSES];                   // alf_luma_coeff_flag[i]
00140   int                          numLumaFilters;                                          // number_of_filters_minus1 + 1
00141   bool                         alfLumaCoeffDeltaFlag;                                   // alf_luma_coeff_delta_flag
00142   std::vector<AlfFilterShape>* filterShapes;
00143   bool                         newFilterFlag[MAX_NUM_CHANNEL_TYPE];
00144 
00145   AlfParam()
00146   {
00147     reset();
00148   }
00149 
00150   void reset()
00151   {
00152     std::memset( enabledFlag, false, sizeof( enabledFlag ) );
00153     std::memset( nonLinearFlag, false, sizeof( nonLinearFlag ) );
00154     std::memset( lumaCoeff, 0, sizeof( lumaCoeff ) );
00155     std::memset( lumaClipp, 0, sizeof( lumaClipp ) );
00156     numAlternativesChroma = 1;
00157     std::memset( chromaCoeff, 0, sizeof( chromaCoeff ) );
00158     std::memset( chromaClipp, 0, sizeof( chromaClipp ) );
00159     std::memset( filterCoeffDeltaIdx, 0, sizeof( filterCoeffDeltaIdx ) );
00160     std::memset( alfLumaCoeffFlag, true, sizeof( alfLumaCoeffFlag ) );
00161     numLumaFilters = 1;
00162     alfLumaCoeffDeltaFlag = false;
00163     memset(newFilterFlag, 0, sizeof(newFilterFlag));
00164   }
00165 
00166   const AlfParam& operator = ( const AlfParam& src )
00167   {
00168     std::memcpy( enabledFlag, src.enabledFlag, sizeof( enabledFlag ) );
00169     std::memcpy( nonLinearFlag, src.nonLinearFlag, sizeof( nonLinearFlag ) );
00170     std::memcpy( lumaCoeff, src.lumaCoeff, sizeof( lumaCoeff ) );
00171     std::memcpy( lumaClipp, src.lumaClipp, sizeof( lumaClipp ) );
00172     numAlternativesChroma = src.numAlternativesChroma;
00173     std::memcpy( chromaCoeff, src.chromaCoeff, sizeof( chromaCoeff ) );
00174     std::memcpy( chromaClipp, src.chromaClipp, sizeof( chromaClipp ) );
00175     std::memcpy( filterCoeffDeltaIdx, src.filterCoeffDeltaIdx, sizeof( filterCoeffDeltaIdx ) );
00176     std::memcpy( alfLumaCoeffFlag, src.alfLumaCoeffFlag, sizeof( alfLumaCoeffFlag ) );
00177     numLumaFilters = src.numLumaFilters;
00178     alfLumaCoeffDeltaFlag = src.alfLumaCoeffDeltaFlag;
00179     filterShapes = src.filterShapes;
00180     std::memcpy(newFilterFlag, src.newFilterFlag, sizeof(newFilterFlag));
00181     return *this;
00182   }
00183 
00184   bool operator==( const AlfParam& other )
00185   {
00186     if( memcmp( enabledFlag, other.enabledFlag, sizeof( enabledFlag ) ) )
00187     {
00188       return false;
00189     }
00190     if( memcmp( nonLinearFlag, other.nonLinearFlag, sizeof( nonLinearFlag ) ) )
00191     {
00192       return false;
00193     }
00194     if( memcmp( lumaCoeff, other.lumaCoeff, sizeof( lumaCoeff ) ) )
00195     {
00196       return false;
00197     }
00198     if( memcmp( lumaClipp, other.lumaClipp, sizeof( lumaClipp ) ) )
00199     {
00200       return false;
00201     }
00202     if( memcmp( chromaCoeff, other.chromaCoeff, sizeof( chromaCoeff ) ) )
00203     {
00204       return false;
00205     }
00206     if( memcmp( chromaClipp, other.chromaClipp, sizeof( chromaClipp ) ) )
00207     {
00208       return false;
00209     }
00210     if( memcmp( filterCoeffDeltaIdx, other.filterCoeffDeltaIdx, sizeof( filterCoeffDeltaIdx ) ) )
00211     {
00212       return false;
00213     }
00214     if( memcmp( alfLumaCoeffFlag, other.alfLumaCoeffFlag, sizeof( alfLumaCoeffFlag ) ) )
00215     {
00216       return false;
00217     }
00218     if( memcmp( newFilterFlag, other.newFilterFlag, sizeof( newFilterFlag ) ) )
00219     {
00220       return false;
00221     }
00222     if( numAlternativesChroma != other.numAlternativesChroma )
00223     {
00224       return false;
00225     }
00226     if( numLumaFilters != other.numLumaFilters )
00227     {
00228       return false;
00229     }
00230     if( alfLumaCoeffDeltaFlag != other.alfLumaCoeffDeltaFlag )
00231     {
00232       return false;
00233     }
00234 
00235     return true;
00236   }
00237 
00238   bool operator!=( const AlfParam& other )
00239   {
00240     return !( *this == other );
00241   }
00242 };
00243 
00244 struct CcAlfFilterParam
00245 {
00246   bool    ccAlfFilterEnabled[2];
00247   bool    ccAlfFilterIdxEnabled[2][MAX_NUM_CC_ALF_FILTERS];
00248   uint8_t ccAlfFilterCount[2];
00249   short   ccAlfCoeff[2][MAX_NUM_CC_ALF_FILTERS][MAX_NUM_CC_ALF_CHROMA_COEFF];
00250   int     newCcAlfFilter[2];
00251   int     numberValidComponents;
00252   CcAlfFilterParam()
00253   {
00254     reset();
00255   }
00256   void reset()
00257   {
00258     std::memset( ccAlfFilterEnabled, false, sizeof( ccAlfFilterEnabled ) );
00259     std::memset( ccAlfFilterIdxEnabled, false, sizeof( ccAlfFilterIdxEnabled ) );
00260     std::memset( ccAlfCoeff, 0, sizeof( ccAlfCoeff ) );
00261     ccAlfFilterCount[0] = ccAlfFilterCount[1] = MAX_NUM_CC_ALF_FILTERS;
00262     numberValidComponents = 3;
00263     newCcAlfFilter[0] = newCcAlfFilter[1] = 0;
00264   }
00265   const CcAlfFilterParam& operator = ( const CcAlfFilterParam& src )
00266   {
00267     std::memcpy( ccAlfFilterEnabled, src.ccAlfFilterEnabled, sizeof( ccAlfFilterEnabled ) );
00268     std::memcpy( ccAlfFilterIdxEnabled, src.ccAlfFilterIdxEnabled, sizeof( ccAlfFilterIdxEnabled ) );
00269     std::memcpy( ccAlfCoeff, src.ccAlfCoeff, sizeof( ccAlfCoeff ) );
00270     ccAlfFilterCount[0] = src.ccAlfFilterCount[0];
00271     ccAlfFilterCount[1] = src.ccAlfFilterCount[1];
00272     numberValidComponents = src.numberValidComponents;
00273     newCcAlfFilter[0] = src.newCcAlfFilter[0];
00274     newCcAlfFilter[1] = src.newCcAlfFilter[1];
00275 
00276     return *this;
00277   }
00278 };
